function renderMonthlyConflicts(month){const conflicts=RijiData.findRecordOverlaps(state.records).filter(item=>item.region===state.region&&(item.first.date.startsWith(month)||item.second.date.startsWith(month)));$('#monthlyConflictSummary').classList.toggle('hidden',!conflicts.length);$('#monthlyConflictSummary').textContent=conflicts.length?`本月存在 ${conflicts.length} 组重叠流水，汇总可能重复计算时间。`:''}
function monthMinutes(month){return state.records.filter(record=>record.date.startsWith(month)&&(!record.region||record.region===state.region)).reduce((total,record)=>total+duration(record.start,record.end),0)}
function renderMonthlySummary(month){const [year,number]=month.split('-').map(Number),days=new Date(year,number,0).getDate(),records=state.records.filter(record=>record.date.startsWith(month)&&(!record.region||record.region===state.region)),total=records.reduce((sum,record)=>sum+duration(record.start,record.end),0),coverage=Math.min(100,Math.round(total/(days*1440)*100)),previousDate=new Date(year,number-2,1),previous=`${previousDate.getFullYear()}-${String(previousDate.getMonth()+1).padStart(2,'0')}`,previousDays=new Date(previousDate.getFullYear(),previousDate.getMonth()+1,0).getDate(),previousCoverage=Math.min(100,Math.round(monthMinutes(previous)/(previousDays*1440)*100)),activeDays=new Set(records.map(record=>record.date)).size,sleepSessions=new Map();records.filter(record=>recordNature(record)==='sleep').forEach(record=>{const key=record.sessionId||record.id,current=sleepSessions.get(key)||{minutes:0,quality:null};current.minutes+=duration(record.start,record.end);if(record.sleepQuality!==null&&record.sleepQuality!==undefined)current.quality=Number(record.sleepQuality);sleepSessions.set(key,current)});const sleeps=[...sleepSessions.values()],averageSleep=sleeps.length?Math.round(sleeps.reduce((sum,item)=>sum+item.minutes,0)/sleeps.length):null,qualities=sleeps.map(item=>item.quality).filter(Number.isFinite),averageQuality=qualities.length?Math.round(qualities.reduce((sum,value)=>sum+value,0)/qualities.length):null;$('#summaryHeading').textContent=`${year}年${number}月的时间账本`;$('#summaryCoverage').textContent=`${coverage}%`;$('#summaryCoverageNote').textContent=`较上月 ${coverage-previousCoverage>=0?'+':''}${coverage-previousCoverage}%`;$('#summaryRecorded').textContent=fmtMin(total);$('#summaryRecordedNote').textContent=`本月 ${activeDays} 天有记录`;$('#summarySleep').textContent=averageSleep===null?'暂无':fmtMin(averageSleep);$('#summarySleepNote').textContent=averageQuality===null?'暂无质量评分':`质量评分 ${averageQuality}`}
function pathForRecord(region,sceneKey){const map=sceneMaps[region],tree=sceneTrees[region];if(!map?.[sceneKey]||!tree?.[sceneKey])return map?.[sceneKey]?.title||'';const names=[];let key=sceneKey;while(key&&map[key]){if(key!=='region')names.unshift(map[key].title);key=tree[key]?.parent}return names.join(' / ')}
