function renderActions(){const opts=activeMap()[editingSceneKey].options.filter(option=>option.kind!=='navigate');$('#actionEditor').innerHTML=opts.map(o=>`<div class="action-card" data-kind="${o.kind}" data-tag="${o.tag||''}" data-nature="${o.timeNature||''}" data-record-mode="${o.recordMode||''}"><input value="${o.name}"><select disabled><option>${o.kind==='睡眠'?'进入睡眠状态':o.timeNature==='positive'?'仅手动同步':'日迹计时'}</option></select><button aria-label="删除">×</button></div>`).join('');$$('.action-card button').forEach(b=>b.onclick=()=>b.parentElement.remove())}
function renderConnections(){const map=activeMap(),links=(map[editingSceneKey].options||[]).filter(option=>option.kind==='navigate');$('#connectionEditor').innerHTML=links.length?links.map(link=>`<div class="connection-row"><span>${link.name}</span><small>→ ${map[link.target]?.title||'已删除场景'}</small><button type="button" data-target="${link.target}" data-name="${link.name}" aria-label="删除联通">×</button></div>`).join(''):'<p class="scene-copy">尚未添加自定义联通。父子通道会自动生成。</p>';$$('.connection-row button').forEach(button=>button.onclick=()=>{const scene=map[editingSceneKey];scene.options=scene.options.filter(option=>!(option.kind==='navigate'&&option.target===button.dataset.target&&option.name===button.dataset.name));save(true);renderConnections();renderScene()})}
