function sceneOptionsForRegion(region){const map=sceneMaps[region],tree=sceneTrees[region],rows=[];function walk(key,depth){if(!map?.[key]||!tree?.[key])return;rows.push(`<option value="${key}">${'　'.repeat(depth)}${map[key].title}</option>`);tree[key].children.forEach(child=>walk(child,depth+1))}walk('region',0);return rows.join('')}
