function renderRegionManager(){const archived=new Set(state.archivedRegions||[]),active=activeRegionNames();$('#activeRegionManager').innerHTML=`<h3>使用中的地区</h3>${active.map(name=>`<div class="region-manager-row"><strong>${name}</strong><button type="button" data-region-action="rename" data-region-name="${name}">重命名</button><button type="button" data-region-action="copy" data-region-name="${name}">复制</button><button type="button" class="danger" data-region-action="archive" data-region-name="${name}">归档</button></div>`).join('')}`;$('#archivedRegionManager').innerHTML=`<h3>已归档</h3>${archived.size?[...archived].map(name=>`<div class="region-manager-row"><strong>${name}</strong><button type="button" data-region-action="restore" data-region-name="${name}">恢复</button><button type="button" class="danger" data-region-action="delete" data-region-name="${name}">删除</button></div>`).join(''):'<p class="region-manager-empty">暂无已归档地区</p>'}`;$$('[data-region-action]').forEach(button=>button.onclick=()=>{if(button.dataset.regionAction==='restore'){RijiData.createBackup(state,'before-region-restore');restoreRegion(button.dataset.regionName);save(true);renderRegionManager();renderRegionOptions();return toast('地区已恢复')}openRegionOperation(button.dataset.regionAction,button.dataset.regionName)})}
function openRegionOperation(mode,name){regionEditMode={mode,name};$('#regionManagerDialog').close();$('#regionNameWrap').classList.toggle('hidden',mode==='archive'||mode==='delete');$('#permanentDeleteRegion').classList.add('hidden');$('#permanentDeleteRegion').dataset.armed='';const labels={rename:'重命名地区',copy:'复制整个地区',archive:'归档地区',delete:'删除已归档地区'};$('#regionEditLabel').textContent=labels[mode];$('#regionEditHeading').textContent=name;$('#regionNameEdit').value=mode==='copy'?`${name} 副本`:name;$('#regionEditMessage').textContent=mode==='archive'?'场景和历史流水都会保留，地区将从日常选择列表中隐藏。':mode==='delete'?'可以继续保留归档，或永久删除该地区及其全部流水。此操作不可撤销。':mode==='copy'?'复制全部场景、行动和联通，不复制历史流水。':'历史流水中的地区名称也会一并更新。';$('#confirmRegionEdit').textContent=mode==='archive'?'归档':mode==='delete'?'保留归档':'确认';if(mode==='delete')$('#permanentDeleteRegion').classList.remove('hidden');$('#regionEditDialog').showModal()}
function renameRegion(oldName,newName){sceneMaps[newName]=sceneMaps[oldName];sceneTrees[newName]=sceneTrees[oldName];delete sceneMaps[oldName];delete sceneTrees[oldName];sceneMaps[newName].region.title=newName;Object.values(sceneMaps[newName]).forEach(scene=>{if(scene.path)scene.path=scene.path.replace(oldName,newName)});state.records.forEach(record=>{if(record.region===oldName)record.region=newName});state.currentScenes[newName]=state.currentScenes[oldName];delete state.currentScenes[oldName];if(state.customScenes?.[oldName]){state.customScenes[newName]=state.customScenes[oldName];delete state.customScenes[oldName]}if(scenes[oldName]){scenes[newName]=scenes[oldName];delete scenes[oldName]}if(state.region===oldName)state.region=newName;sceneTree=sceneTrees[state.region]}
function copyRegion(source,name){sceneMaps[name]=RijiData.clone(sceneMaps[source]);sceneTrees[name]=RijiData.clone(sceneTrees[source]);sceneMaps[name].region.title=name;Object.values(sceneMaps[name]).forEach(scene=>{if(scene.path)scene.path=scene.path.replace(source,name)});state.currentScenes[name]='region'}
function archiveRegion(name){if(activeRegionNames().length<2)return toast('至少需要保留一个使用中的地区');state.archivedRegions=[...new Set([...state.archivedRegions,name])];if(state.region===name){state.region=activeRegionNames().find(region=>region!==name);sceneTree=sceneTrees[state.region];editingSceneKey=state.currentScenes[state.region]||'region';$('#regionSelect').value=state.region}}
function restoreRegion(name){state.archivedRegions=state.archivedRegions.filter(region=>region!==name)}
function deleteRegionPermanently(name){const removed=state.records.filter(record=>record.region===name);state.deletedRecordIds=[...new Set([...state.deletedRecordIds,...removed.map(record=>record.id)])];state.records=state.records.filter(record=>record.region!==name);delete sceneMaps[name];delete sceneTrees[name];delete state.currentScenes[name];delete state.customScenes?.[name];delete scenes[name];state.archivedRegions=state.archivedRegions.filter(region=>region!==name)}
