$('#confirmRegionEdit').onclick=()=>{if(!regionEditMode)return;const {mode,name}=regionEditMode,newName=$('#regionNameEdit').value.trim();if(mode==='delete')return $('#regionEditDialog').close();if((mode==='rename'||mode==='copy')&&!newName)return toast('请输入地区名称');if(mode==='copy'&&sceneMaps[newName])return toast('该地区名称已经存在');if(mode==='rename'&&newName!==name&&sceneMaps[newName])return toast('该地区名称已经存在');if(mode==='archive'&&activeRegionNames().length<2)return toast('至少需要保留一个使用中的地区');RijiData.createBackup(state,`before-region-${mode}`);if(mode==='rename'&&newName!==name)renameRegion(name,newName);if(mode==='copy')copyRegion(name,newName);if(mode==='archive')archiveRegion(name);save(true);$('#regionEditDialog').close();renderRegionOptions();renderTree();openSceneEditor(editingSceneKey);renderScene();renderTimeline();renderDistribution();toast(mode==='archive'?'地区已归档':mode==='copy'?'地区副本已创建':'地区名称已更新')};
