$('#saveScene').onclick=()=>{const map=activeMap(),s=map[editingSceneKey],oldTitle=s.title,links=s.options.filter(option=>option.kind==='navigate');s.title=$('#sceneNameInput').value.trim()||s.title;s.icon=$('#sceneIconInput').value;s.copy=$('#sceneDescInput').value.trim();const actions=$$('.action-card').map(card=>{const name=card.querySelector('input').value.trim()||'未命名行动',kind=card.dataset.kind,tag=card.dataset.tag||'',timeNature=card.dataset.nature||(kind==='娱乐'?'neutral':'positive'),recordMode=card.dataset.recordMode||(timeNature==='positive'?'external':'internal');if(kind==='睡眠')return {name,hint:'开始睡眠记录',kind:'睡眠',tag:'',timeNature:'sleep',recordMode:'none'};return {name,hint:`${tag||kind} · 可计时`,kind,tag,timeNature,recordMode}});s.options=[...actions,...links];if(oldTitle!==s.title)Object.values(map).forEach(scene=>(scene.options||[]).forEach(option=>{if(option.target===editingSceneKey){option.hint=`通往${s.title} · 不计时`;if(option.name===`前往${oldTitle}`||option.name==='前往新场景')option.name=`前往${s.title}`}}));$('#editName').textContent=s.title;save(true);renderTree();renderScene();renderConnections();toast('场景修改已保存')};
