$('#newScene').onclick=()=>{const map=activeMap(),parent=editingSceneKey||'region',key=`scene_${Date.now()}`;sceneTree[key]={parent,children:[]};sceneTree[parent].children.push(key);map[key]={title:'新场景',icon:'pin',path:'',copy:'这是一个新场景。请填写它的描述，并添加行动或通道。',options:[{name:`返回${map[parent].title}`,hint:`通往${map[parent].title} · 不计时`,kind:'navigate',target:parent,timeNature:'passage',recordMode:'none',tag:''}]};map[parent].options.push({name:'前往新场景',hint:'通往新场景 · 不计时',kind:'navigate',target:key,timeNature:'passage',recordMode:'none',tag:''});editingSceneKey=key;save(true);renderTree();openSceneEditor(key);toast(`已在${map[parent].title}下创建场景`)};
