$('#confirmDeleteScene').onclick=()=>{const map=activeMap(),key=editingSceneKey,parent=sceneTree[key].parent,mode=$('#deleteChildrenMode').value,removed=[];function collect(node){removed.push(node);sceneTree[node].children.forEach(collect)}if(mode==='all')collect(key);else{removed.push(key);sceneTree[key].children.forEach(child=>{sceneTree[child].parent=parent;sceneTree[parent].children.push(child)})}sceneTree[parent].children=sceneTree[parent].children.filter(child=>child!==key);removed.forEach(node=>{delete sceneTree[node];delete map[node]});Object.values(map).forEach(scene=>{scene.options=(scene.options||[]).filter(option=>!removed.includes(option.target))});const current=state.currentScenes?.[state.region];if(removed.includes(current))state.currentScenes[state.region]=parent;editingSceneKey=parent;save(true);$('#deleteSceneDialog').close();openSceneEditor(parent);renderScene();toast('场景已删除，历史流水已保留')};
