function renderDataManager(){const backups=RijiData.backups(),lastDate=state.records.map(record=>record.date).sort().at(-1)||'暂无',reasonLabels={auto:'自动备份',manual:'手动备份','before-cloud-merge':'云端合并前','before-scene-conflict-resolution':'场景冲突处理前','before-timer-conflict-resolution':'计时冲突处理前','before-overlap-resolution':'重叠处理前','before-import':'导入前','before-restore':'恢复前'};$('#dataStats').innerHTML=`<div><span>数据版本</span><strong>v${RijiData.SCHEMA_VERSION}</strong></div><div><span>流水记录</span><strong>${state.records.length}</strong></div><div><span>最后记录</span><strong>${lastDate}</strong></div>`;$('#backupList').innerHTML=backups.length?backups.map(item=>`<div class="backup-row"><div><strong>${new Date(item.createdAt).toLocaleString('zh-CN')}</strong><small>${reasonLabels[item.reason]||'本地备份'} · ${item.recordCount} 条记录</small></div><button type="button" data-backup-id="${item.id}">恢复</button></div>`).join(''):'<p class="scene-copy">还没有本地备份。</p>';$$('[data-backup-id]').forEach(button=>button.onclick=()=>{RijiData.createBackup(state,'before-restore');RijiData.restore(button.dataset.backupId);location.reload()})}
function resolveOverlap(action,firstId,secondId){const first=state.records.find(record=>String(record.id)===String(firstId)),second=state.records.find(record=>String(record.id)===String(secondId));if(!first||!second||first.date!==second.date)return toast('该冲突需要手动编辑');RijiData.createBackup(state,'before-overlap-resolution');if(action==='trim'&&minutes(second.start)>minutes(first.start))first.end=second.start;else if(action==='shift'&&minutes(first.end)<minutes(second.end))second.start=first.end;else return toast('无法自动处理该包含关系，请手动编辑');const changed=action==='trim'?first:second;changed.updatedAt=clockNow().toISOString();save();renderRecordConflictAudit();renderTimeline();renderDistribution();toast(action==='trim'?'已截断前一条流水':'已后移后一条流水')}
function renderRecordConflictAudit(){const conflicts=RijiData.findRecordOverlaps(state.records);$('#recordConflictCount').textContent=String(conflicts.length);$('#recordConflictList').innerHTML=conflicts.length?conflicts.map(item=>{const sameDay=item.first.date===item.second.date,canTrim=sameDay&&minutes(item.second.start)>minutes(item.first.start),canShift=sameDay&&minutes(item.first.end)<minutes(item.second.end);return `<div class="record-conflict-row"><button type="button" data-conflict-record="${item.first.id}"><strong>${item.first.name}</strong><small>${item.first.date} · ${item.first.start}–${item.first.end} · ${item.region}</small></button><div class="conflict-actions"><span>重叠 ${item.minutes} 分钟</span>${canTrim?`<button type="button" data-overlap-action="trim" data-first="${item.first.id}" data-second="${item.second.id}">截断前项</button>`:''}${canShift?`<button type="button" data-overlap-action="shift" data-first="${item.first.id}" data-second="${item.second.id}">后移后项</button>`:''}</div><button type="button" data-conflict-record="${item.second.id}"><strong>${item.second.name}</strong><small>${item.second.date} · ${item.second.start}–${item.second.end} · ${item.region}</small></button></div>`}).join(''):'<p class="scene-copy">没有发现重叠流水。</p>';$$('[data-conflict-record]').forEach(button=>button.onclick=()=>{$('#dataDialog').close();openRecordEditor(button.dataset.conflictRecord)});$$('[data-overlap-action]').forEach(button=>button.onclick=()=>resolveOverlap(button.dataset.overlapAction,button.dataset.first,button.dataset.second))}
function renderCloudAccount(){const session=RijiCloud.session(),signedIn=Boolean(session?.access_token),hasConflict=Boolean(state.sync?.sceneConflict),hasTimerConflict=Boolean(state.sync?.timerConflict);$('#cloudLogin').classList.toggle('hidden',signedIn);$('#cloudAccount').classList.toggle('hidden',!signedIn);$('#syncNow').classList.toggle('hidden',!signedIn);$('#sceneConflict').classList.toggle('hidden',!signedIn||!hasConflict);$('#timerConflict').classList.toggle('hidden',!signedIn||!hasTimerConflict);$('#cloudUser').textContent=session?.user?.email||'';$('#cloudSummary').textContent=signedIn?(hasConflict?'需要选择要保留的场景版本':hasTimerConflict?'需要处理计时会话冲突':state.sync?.lastSyncedAt?`上次同步：${new Date(state.sync.lastSyncedAt).toLocaleString('zh-CN')}`:'已登录，尚未完成首次同步'):'尚未连接云端账户'}
async function resolveSceneConflict(useCloud){const conflict=state.sync?.sceneConflict;if(!conflict)return;RijiData.createBackup(state,'before-scene-conflict-resolution');if(useCloud)Object.assign(state,RijiData.clone(conflict.remoteConfig));state.sync.sceneRevision=Math.max(conflict.localRevision||0,conflict.remoteRevision||0)+1;state.sync.sceneConflict=null;RijiData.save(state);setCloudMessage('正在保存场景选择…','pending');try{await RijiCloud.sync(state);toast(useCloud?'已采用云端场景版本':'已保留此设备的场景版本');setTimeout(()=>location.reload(),500)}catch(error){setCloudMessage(`同步失败：${error.message}`,'error');toast('选择已保存在本机，联网后请再次同步')}}
async function resolveTimerConflict(mode){const conflict=state.sync?.timerConflict;if(!conflict)return;RijiData.createBackup(state,'before-timer-conflict-resolution');if(mode==='both'&&conflict.remoteTimer)recordTimer(RijiData.clone(conflict.remoteTimer),Date.parse(conflict.detectedAt)||Date.now());if(mode==='cloud')state.activeTimer=RijiData.clone(conflict.remoteTimer);state.sync.timerRevision=Math.max(conflict.localRevision||0,conflict.remoteRevision||0)+1;state.sync.timerConflict=null;RijiData.save(state);setCloudMessage('正在保存计时选择…','pending');try{await RijiCloud.sync(state);toast(mode==='cloud'?'已采用云端计时会话':mode==='both'?'已保存云端片段并保留本机会话':'已保留本机会话');setTimeout(()=>location.reload(),500)}catch(error){setCloudMessage(`同步失败：${error.message}`,'error');toast('选择已保存在本机，联网后请再次同步')}}
function setCloudMessage(message,stateName=''){$('#cloudSummary').textContent=message;$('#cloudSummary').dataset.state=stateName}
function cloudErrorMessage(error,prefix){if(error.code==='over_email_send_rate_limit'||/email rate limit/i.test(error.message))return'确认邮件发送额度已用完，请先检查收件箱和垃圾邮件，稍后再试';if(error.status===429)return'请求过于频繁，请等待几分钟后再试';return`${prefix}：${error.message}`}
async function runCloudSync(){setCloudMessage('正在与云端合并数据…','pending');try{const result=await RijiCloud.sync(state);if(result.signedOut){setCloudMessage('请先登录云同步','error');return toast('请先登录云同步')}renderCloudAccount();if(result.changed){setCloudMessage('已合并其他设备的数据','success');toast('已合并其他设备的数据');setTimeout(()=>location.reload(),700)}else{setCloudMessage('云端数据已同步','success');toast('云端数据已同步')}}catch(error){const message=error.status===404?'云端数据表尚未初始化':`同步失败：${error.message}`;setCloudMessage(message,'error');toast(message)}}
async function cloudAuth(mode){const email=$('#cloudEmail').value.trim(),password=$('#cloudPassword').value,buttons=[$('#cloudSignin'),$('#cloudSignup')];if(!email||password.length<8){setCloudMessage('请输入有效邮箱和至少 8 位密码','error');return toast('请输入邮箱和至少 8 位密码')}buttons.forEach(button=>button.disabled=true);setCloudMessage(mode==='signup'?'正在创建账户…':'正在登录…','pending');try{const result=await RijiCloud.authenticate(email,password,mode);if(result.needsConfirmation){setCloudMessage(`确认邮件已发送至 ${email}，请点击邮件中的链接后再登录`,'success');return toast('账户已创建，请检查确认邮件')}renderCloudAccount();await runCloudSync()}catch(error){const message=cloudErrorMessage(error,mode==='signup'?'注册失败':'登录失败');setCloudMessage(message,'error');toast(message)}finally{buttons.forEach(button=>button.disabled=false)}}
$('#cloudSignin').onclick=()=>cloudAuth('signin');$('#cloudSignup').onclick=()=>cloudAuth('signup');$('#syncNow').onclick=runCloudSync;$('#cloudSignout').onclick=()=>{RijiCloud.signOut();renderCloudAccount();toast('已退出云同步，本地数据仍保留')};
$('#keepLocalScenes').onclick=()=>resolveSceneConflict(false);$('#useCloudScenes').onclick=()=>resolveSceneConflict(true);
$('#keepLocalTimer').onclick=()=>resolveTimerConflict('local');$('#saveBothTimers').onclick=()=>resolveTimerConflict('both');$('#useCloudTimer').onclick=()=>resolveTimerConflict('cloud');
window.addEventListener('riji-cloud-status',event=>{const {status,message}=event.detail,$state=$('#syncState');$state.dataset.status=status;$state.querySelector('b').textContent=message});
$('#openDataManager').onclick=()=>{pendingImportData=null;$('#importPreview').classList.add('hidden');renderDataManager();renderRecordConflictAudit();renderCloudAccount();renderClockAudit();$('#dataDialog').showModal()};
$('#exportJson').onclick=()=>{const stamp=new Date().toISOString().slice(0,10);downloadFile(`日迹备份-${stamp}.json`,JSON.stringify(RijiData.envelope(state),null,2),'application/json;charset=utf-8');toast('JSON 备份已导出')};
$('#exportCsv').onclick=()=>{const fields=['日期','开始','结束','行动','时间性质','Tag','地区','场景','来源','睡眠质量'],escape=value=>`"${String(value??'').replaceAll('"','""')}"`,rows=state.records.map(record=>[record.date,record.start,record.end,record.name,record.timeNature,record.tag,record.region||'上海',record.path,record.source,record.sleepQuality].map(escape).join(','));downloadFile(`日迹流水-${new Date().toISOString().slice(0,10)}.csv`,`\ufeff${fields.join(',')}\r\n${rows.join('\r\n')}`,'text/csv;charset=utf-8');toast('CSV 流水已导出')};
$('#createBackup').onclick=()=>{RijiData.createBackup(state,'manual');renderDataManager();toast('本地备份已创建')};
$('#chooseImport').onclick=()=>$('#importFile').click();
$('#importFile').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{pendingImportData=RijiData.parseImport(await file.text());$('#importSummary').textContent=`${file.name} · 数据版本 v${pendingImportData.schemaVersion} · ${pendingImportData.records.length} 条流水。合并会保留两边记录并检测场景冲突；覆盖会替换当前内容。两种方式都会先备份。`;$('#importPreview').classList.remove('hidden')}catch(error){pendingImportData=null;toast(`无法导入：${error.message}`)}event.target.value=''};
$('#mergeImport').onclick=()=>{if(!pendingImportData)return;RijiData.createBackup(state,'before-import');RijiData.save(RijiData.merge(state,pendingImportData));location.reload()};
$('#applyImport').onclick=()=>{if(!pendingImportData)return;RijiData.createBackup(state,'before-import');pendingImportData.sync={...(pendingImportData.sync||{}),sceneRevision:(state.sync?.sceneRevision||0)+1,timerRevision:(state.sync?.timerRevision||0)+1,sceneConflict:null,timerConflict:null};RijiData.save(pendingImportData);location.reload()};
$('#resetDemo').onclick=()=>{RijiData.createBackup(state,'before-reset');localStorage.removeItem('riji-state');location.reload()};
function renderClock(){const now=clockNow(),clock=RijiCloud.clock(),minutesOff=Math.round(Math.abs(clock.offsetMs)/60000),warning=minutesOff>=2,compact=window.innerWidth<=900,formatted=new Intl.DateTimeFormat('zh-CN',compact?{timeStyle:'short',hour12:false}:{dateStyle:'medium',timeStyle:'medium',hour12:false}).format(now);$('#clock').textContent=`${formatted}${warning?' · 偏差警告':''}`;$('#clock').dataset.state=warning?'warning':'calibrated';$('#clock').title=clock.checkedAt?`已按云端校准${warning?`，设备时间偏差约 ${minutesOff} 分钟`:''} · ${new Date(clock.checkedAt).toLocaleString('zh-CN')}`:'尚未连接云端校准时间'}renderClock();setInterval(renderClock,1000);window.addEventListener('resize',renderClock);window.addEventListener('riji-clock-calibrated',renderClock);
function renderClockAudit(){const clock=RijiCloud.clock(),minutesOff=Math.round(Math.abs(clock.offsetMs)/60000),warning=minutesOff>=2,summary=$('#clockAuditSummary');summary.dataset.state=warning?'warning':'ready';summary.textContent=clock.checkedAt?`上次校准：${new Date(clock.checkedAt).toLocaleString('zh-CN')} · ${warning?`设备时间偏差约 ${minutesOff} 分钟`:'设备时间正常'}`:'尚未成功读取服务器时间'}
$('#recalibrateClock').onclick=async()=>{const button=$('#recalibrateClock');button.disabled=true;button.textContent='校准中…';await RijiCloud.calibrate();renderClock();renderClockAudit();button.disabled=false;button.textContent='重新校准';toast(RijiCloud.clock().checkedAt?'时间校准完成':'未能读取服务器时间，请稍后重试')};window.addEventListener('riji-clock-calibrated',renderClockAudit);renderClockAudit();
function renderMonthOptions(){const current=clockNow(),currentMonth=`${current.getFullYear()}-${String(current.getMonth()+1).padStart(2,'0')}`,months=[...new Set([currentMonth,...state.records.map(record=>record.date.slice(0,7))])].sort().reverse(),selected=months.includes($('#monthSelect').value)?$('#monthSelect').value:currentMonth;$('#monthSelect').innerHTML=months.map(month=>{const [year,number]=month.split('-');return `<option value="${month}">${year}年${Number(number)}月</option>`}).join('');$('#monthSelect').value=selected}renderMonthOptions();$$('.segmented button').forEach(button=>button.onclick=()=>{distributionMode=button.textContent.includes('自然')?'natural':'recorded';$$('.segmented button').forEach(item=>item.classList.toggle('active',item===button));$('.distribution .section-title p').textContent=distributionMode==='natural'?'占本月自然时间的比例':'占已记录活动时间的比例';renderDistribution()});$('#monthSelect').onchange=renderDistribution;
editingSceneKey=state.currentScenes?.[state.region]||(activeMap().desk?'desk':'home');renderScene();renderTimeline();renderDistribution();openSceneEditor(editingSceneKey);
renderCloudAccount();RijiCloud.calibrate();if(RijiCloud.session())runCloudSync();
if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(()=>{});
